const inputData = $input.first().json;

const duration = (inputData.Duration || "").toLowerCase().trim();

let durationInMinutes = 0;

if (duration.includes("minute") || duration.includes("min") || duration.includes("mins")) {
  durationInMinutes = parseFloat(duration);
} else if (duration.includes("hour") || duration.includes("hr") || duration.includes("hrs")) {
  durationInMinutes = parseFloat(duration) * 60;
}

return [
  {
    json: {
      ...inputData,
      durationInMinutes
    }
  }
];

