// New meeting submitted through the form
const newMeeting = $('Edit Fields (Set Node)').first().json;

const newStart = new Date(newMeeting['Date/Time']);
const newDuration = Number(
  newMeeting['Duration(mins)']
  ?? newMeeting['Duration (minutes)']
  ?? newMeeting.durationInMinutes
);

const newEnd = new Date(
  newStart.getTime() + newDuration * 60 * 1000
);

const bufferMilliseconds = 60 * 60 * 1000;
const existingMeetings = $input.all();

let conflictDetails = null;

for (const item of existingMeetings) {
  const meeting = item.json;

  // Ignore blank output and cancelled meetings
  if (!meeting['Date/Time']) continue;
  if (
    String(meeting.Status || '').toLowerCase() === 'cancelled'
  ) continue;

  const existingStart = new Date(meeting['Date/Time']);

  const existingDuration = Number(
    meeting['Duration(mins)']
    ?? meeting['Duration (minutes)']
    ?? 0
  );

  const existingEnd = new Date(
    existingStart.getTime() + existingDuration * 60 * 1000
  );

  /*
    Conflict exists when the meetings overlap,
    or when the gap between them is less than 60 minutes.
  */
  const hasConflict =
    newStart.getTime() < existingEnd.getTime() + bufferMilliseconds &&
    newEnd.getTime() + bufferMilliseconds > existingStart.getTime();

  if (hasConflict) {
    conflictDetails = {
      title: meeting.Title,
      dateTime: meeting['Date/Time'],
      durationInMinutes: existingDuration,
      id: meeting.ID
    };

    break;
  }
}

return [
  {
    json: {
      ...newMeeting,
      conflict: conflictDetails !== null,
      conflictDetails
    }
  }
];

