const now = new Date();

const pastMeetings = $input.all().filter(item => {
  const meeting = item.json;

  const status = String(meeting.Status || '').trim();

  // Only process Scheduled or Reminded meetings
  if (!['Scheduled', 'Reminded'].includes(status)) {
    return false;
  }

  const startTime = new Date(meeting['Date/Time']);

  const durationMinutes = Number(
    meeting['Duration(mins)'] ??
    meeting['Duration (minutes)'] ??
    0
  );

  const endTime = new Date(
    startTime.getTime() + durationMinutes * 60 * 1000
  );

  return endTime < now;
});

return pastMeetings;

const meetings = $input.all().map(item => item.json);

// Asia/Karachi is UTC+5
const KARACHI_OFFSET_MS = 5 * 60 * 60 * 1000;

// Convert the current instant into a Karachi-based clock value
const nowKarachi = new Date(Date.now() + KARACHI_OFFSET_MS);

// JavaScript: Sunday = 0, Monday = 1, ..., Saturday = 6
const currentDay = nowKarachi.getUTCDay();

// Number of days since Monday
const daysSinceMonday = (currentDay + 6) % 7;

// Monday at 00:00 in Karachi, represented as a shifted UTC value
const weekStartShifted = new Date(Date.UTC(
  nowKarachi.getUTCFullYear(),
  nowKarachi.getUTCMonth(),
  nowKarachi.getUTCDate() - daysSinceMonday,
  0,
  0,
  0,
  0
));

// Next Monday at 00:00
const weekEndShifted = new Date(
  weekStartShifted.getTime() + 7 * 24 * 60 * 60 * 1000
);

// Convert shifted Karachi boundaries back to actual timestamps
const weekStart = new Date(
  weekStartShifted.getTime() - KARACHI_OFFSET_MS
);

const weekEnd = new Date(
  weekEndShifted.getTime() - KARACHI_OFFSET_MS
);

const weeklyMeetings = meetings
  .filter(meeting => {
    if (!meeting['Date/Time']) return false;

    const meetingTime = new Date(meeting['Date/Time']);

    if (Number.isNaN(meetingTime.getTime())) return false;

    return meetingTime >= weekStart && meetingTime < weekEnd;
  })
  .sort((a, b) => {
    return (
      new Date(a['Date/Time']).getTime() -
      new Date(b['Date/Time']).getTime()
    );
  });

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function formatKarachiDate(isoDate) {
  return new Intl.DateTimeFormat('en-PK', {
    timeZone: 'Asia/Karachi',
    weekday: 'short',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  }).format(new Date(isoDate));
}

function formatDateOnly(date) {
  return new Intl.DateTimeFormat('en-PK', {
    timeZone: 'Asia/Karachi',
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  }).format(date);
}

let html;

if (weeklyMeetings.length === 0) {
  html = `
    <div style="font-family: Arial, sans-serif;">
      <h2>Weekly Meeting Digest</h2>
      <p>No meetings scheduled for this week.</p>
    </div>
  `;
} else {
  const rows = weeklyMeetings.map(meeting => `
    <tr>
      <td style="padding:8px;border:1px solid #cccccc;">
        ${escapeHtml(meeting.Title)}
      </td>

      <td style="padding:8px;border:1px solid #cccccc;">
        ${escapeHtml(formatKarachiDate(meeting['Date/Time']))}
      </td>

      <td style="padding:8px;border:1px solid #cccccc;">
        ${escapeHtml(meeting.Attendees)}
      </td>

      <td style="padding:8px;border:1px solid #cccccc;">
        ${escapeHtml(meeting.Status)}
      </td>

      <td style="padding:8px;border:1px solid #cccccc;">
        ${escapeHtml(meeting.Gist)}
      </td>
    </tr>
  `).join('');

  const weekEndDisplay = new Date(
    weekEnd.getTime() - 24 * 60 * 60 * 1000
  );

  html = `
    <div style="font-family: Arial, sans-serif;">
      <h2>Weekly Meeting Digest</h2>

      <p>
        Meetings from
        <strong>${formatDateOnly(weekStart)}</strong>
        to
        <strong>${formatDateOnly(weekEndDisplay)}</strong>
      </p>

      <table style="border-collapse:collapse;width:100%;">
        <thead>
          <tr style="background:#e8f3ef;">
            <th style="padding:8px;border:1px solid #cccccc;">Title</th>
            <th style="padding:8px;border:1px solid #cccccc;">Date/Time</th>
            <th style="padding:8px;border:1px solid #cccccc;">Attendees</th>
            <th style="padding:8px;border:1px solid #cccccc;">Status</th>
            <th style="padding:8px;border:1px solid #cccccc;">Gist</th>
          </tr>
        </thead>

        <tbody>
          ${rows}
        </tbody>
      </table>
    </div>
  `;
}

return [
  {
    json: {
      meetingCount: weeklyMeetings.length,
      weekStart: weekStart.toISOString(),
      weekEnd: weekEnd.toISOString(),
      html
    }
  }
];

const now = new Date();
const thirtyDaysAgo = new Date(
  now.getTime() - 30 * 24 * 60 * 60 * 1000
);

const archivedOn = now.toISOString();
const inputItems = $input.all();

const output = [];

inputItems.forEach((item, index) => {
  const meeting = item.json;
  const meetingDate = new Date(meeting['Date/Time']);

  const shouldArchive =
    String(meeting.Status || '').trim() === 'Done' &&
    !Number.isNaN(meetingDate.getTime()) &&
    meetingDate < thirtyDaysAgo;

  if (shouldArchive) {
    output.push({
      json: {
        ...meeting,
        ArchivedOn: archivedOn
      },
      pairedItem: {
        item: index
      }
    });
  }
});

return output;

